.motion-sample {
  --ml-accent: #c6f66b;
  --ml-ink: #13210d;
  box-sizing: border-box;
  position: relative;
  display: grid;
  place-items: center;
  width: 104px;
  height: 68px;
  border-radius: 10px;
  color: var(--ml-ink);
  background: var(--ml-accent);
  font: 700 20px/1 system-ui, sans-serif;
}

@keyframes ml-stagger-bars {
  0%, 70%, 100% { background-size: 22px 8px; }
  33% { background-size: 22px 32px; }
}
@keyframes ml-stagger-edge {
  0%, 70%, 100% { height: 8px; }
  33% { height: 32px; }
}
.motion-sample { width: 94px; height: 40px; border-radius: 0; color: transparent; background: linear-gradient(var(--ml-accent), var(--ml-accent)) center bottom / 22px 24px no-repeat; animation: ml-stagger-bars 1.7s ease-in-out .14s infinite; }
.motion-sample::before, .motion-sample::after { content: ""; position: absolute; bottom: 0; width: 22px; height: 24px; background: var(--ml-accent); border-radius: 4px 4px 0 0; animation: ml-stagger-edge 1.7s ease-in-out infinite; }
.motion-sample::before { left: 0; }
.motion-sample::after { right: 0; animation-delay: .28s; }

@media (prefers-reduced-motion: reduce) {
  .motion-sample {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
    filter: none !important;
    clip-path: none !important;
    letter-spacing: normal !important;
  }
  .motion-sample::before,
  .motion-sample::after {
    animation: none !important;
    transition: none !important;
  }
}

